script:
frappe.ui.form.on('Material Request', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button('Create Bid', function() {
                if (frm.doc.concept_note) {
                    frappe.call({
                        method: 'frappe.client.get_value',
                        args: {
                            doctype: 'Concept Note',
                            filters: { name: frm.doc.concept_note },
                            fieldname: ['status']
                        },
                        callback: function(r) {
                            if (r.message) {
                                const fetched_status = r.message.status;
                                console.log("Fetched Concept Note Status:", fetched_status);
                                if ((fetched_status || '').trim().toLowerCase() !== 'approved') {
                                    frappe.msgprint('You can only create a Bid if the linked Concept Note is Approved.');
                                } else {
                                    frappe.new_doc('Bid Creation', {
                                        material_request: frm.doc.name
                                    });
                                }
                            } else {
                                frappe.msgprint('Concept Note not found.');
                            }
                        }
                    });
                } else {
                    frappe.msgprint('No Concept Note linked with this Material Request.');
                }
            }, 'Actions');
        }
    }
});

frappe.ui.form.on('Bid Creation', {
    refresh: function(frm) {
        frm.toggle_display('committee_members', false);
    },
    committee_type: function(frm) {
        if (frm.doc.committee_type) {
            frm.toggle_display('committee_members', true); 
        } else {
            frm.toggle_display('committee_members', false);
        }
    }
});

frappe.ui.form.on('Bid Creation', {
    refresh: function(frm) {
        frm.set_value('current_status', frm.doc.workflow_state);
    },
    workflow_state: function(frm) {
        frm.set_value('current_status', frm.doc.workflow_state);
    }
});

frappe.ui.form.on('Material Request', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button('Create Bid', function() {
                // Correct: Object, not a string
                frappe.db.exists('Bid Creation', { material_request: frm.doc.name })
                    .then(function(exists) {
                        if (exists) {
                            frappe.msgprint('Bid already exists for this Material Request.');
                        } else {
                            frappe.new_doc('Bid Creation', {
                                material_request: frm.doc.name
                            });
                        }
                    });
            }, 'Actions');
        }
    }
});

frappe.ui.form.on('Bid', {
    validate: function(frm) {
        // Sirf Procurement Officer role ke liye chale
        if (frappe.user.has_role("Procurement Officer")) {
            
            // Sirf jab state "Approved by MD" ho tab check kare
            if (frm.doc.workflow_state === "Approved") {
                
                let chairman_count = 0;

                // members child table loop
                (frm.doc.members || []).forEach(function(row) {
                    if (row.is_chairman) {
                        chairman_count += 1;
                    }
                });

                // Agar chairman select nahi hai
                if (chairman_count === 0) {
                    frappe.throw(__('Please select a Chairman before saving or submitting the Bid.'));
                }

                // Agar ek se zyada chairman select kar diye
                if (chairman_count > 1) {
                    frappe.throw(__('Only one Chairman can be selected.'));
                }
            }
        }
    }
});

frappe.ui.form.on('Bid Creation', {
    refresh: function(frm) {
        if (frappe.user.has_role('PDofficer') || frappe.user.has_role('Procurement Officer')) {
            if (frm.doc.status == "Approved by MD") {
                frappe.msgprint("This Bid has been Approved by MD.");
            }
        }
    }
});

frappe.ui.form.on('Material Request', {
    refresh(frm) {
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button('Create Bid', () => {

                // Check if a Bid Creation already exists for this Material Request
                frappe.db.exists('Bid Creation', {
                    material_request: frm.doc.name
                }).then(exists => {
                    if (exists) {
                        // If exists, show message and stop
                        frappe.msgprint('❗ A Bid already exists for this Material Request: ' + exists);
                    } else {
                        // Else, open a new Bid Creation form with material_request pre-filled
                        frappe.new_doc('Bid Creation', {
                            material_request: frm.doc.name
                        });
                    }
                });

            }, 'Actions'); // You can also remove 'Actions' if you want the button at top
        }
    }
});

frappe.ui.form.on('Material Request', {
    refresh(frm) {
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button('Create Bid', () => {

                frappe.db.get_list('Bid Creation', {
                    filters: {
                        material_request: frm.doc.name
                    },
                    fields: ['name'],
                    limit: 1
                }).then(records => {
                    if (records.length) {
                        frappe.msgprint('❗ A Bid already exists for this Material Request: ' + records[0].name);
                    } else {
                        frappe.new_doc('Bid Creation', { material_request: frm.doc.name });
                    }
                });

            }, 'Actions');
        }
    }
});

frappe.ui.form.on("Bid Creation", {
    before_workflow_action: function(frm, action) {
        if (action === "Select Chairman") {
            frappe.prompt([
                {
                    fieldtype: "Link",
                    label: "Select Chairman",
                    fieldname: "chairman",
                    options: "User",
                    reqd: 1,
                    get_query: () => {
                        return {
                            filters: {
                                "name": ["in", frm.doc.committee_members.map(r => r.user)]
                            }
                        };
                    }
                }
            ], function(values){
                frm.doc.committee_members.forEach(row => {
                    row.is_chairman = (row.user === values.chairman) ? 1 : 0;
                });
                frm.refresh_field("committee_members");
                frappe.msgprint("Chairman selected successfully!");
            }, "Select Committee Chairman");
            
            throw "Please select Chairman first!";
        }
    }
});

