frappe.ui.form.on('Committee Member1', {
    is_chairman: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        // 👉 केवल तब चले जब user ने अभी checkbox TRUE किया है
        if (row.is_chairman !== 1) {
            return;  // uncheck या refresh case → कुछ मत करो
        }

        // 👉 सिर्फ Managing Officer ही select कर सके
        if (!frappe.user.has_role("Managing Officer")) {
            frappe.msgprint("केवल Managing Officer ही Chairman select कर सकता है।");

            // तुरंत वापस uncheck कर दो
            frappe.model.set_value(cdt, cdn, "is_chairman", 0);
        }
    }
});
